sys_script_include.script:
var GSTINUtil = Class.create();
GSTINUtil.prototype = {

    CHARS: '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ',

    // 2-char PAN-holder state, 5 letters, 4 digits, 1 letter, entity code (1-9 or A-Z), 'Z', check char
    FORMAT: /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/,

    STATES: {
        '01': 'Jammu and Kashmir',
        '02': 'Himachal Pradesh',
        '03': 'Punjab',
        '04': 'Chandigarh',
        '05': 'Uttarakhand',
        '06': 'Haryana',
        '07': 'Delhi',
        '08': 'Rajasthan',
        '09': 'Uttar Pradesh',
        '10': 'Bihar',
        '11': 'Sikkim',
        '12': 'Arunachal Pradesh',
        '13': 'Nagaland',
        '14': 'Manipur',
        '15': 'Mizoram',
        '16': 'Tripura',
        '17': 'Meghalaya',
        '18': 'Assam',
        '19': 'West Bengal',
        '20': 'Jharkhand',
        '21': 'Odisha',
        '22': 'Chhattisgarh',
        '23': 'Madhya Pradesh',
        '24': 'Gujarat',
        '25': 'Daman and Diu',
        '26': 'Dadra and Nagar Haveli and Daman and Diu',
        '27': 'Maharashtra',
        '28': 'Andhra Pradesh (Old)',
        '29': 'Karnataka',
        '30': 'Goa',
        '31': 'Lakshadweep',
        '32': 'Kerala',
        '33': 'Tamil Nadu',
        '34': 'Puducherry',
        '35': 'Andaman and Nicobar Islands',
        '36': 'Telangana',
        '37': 'Andhra Pradesh',
        '38': 'Ladakh',
        '97': 'Other Territory',
        '99': 'Centre Jurisdiction'
    },

    initialize: function() {},

    // Trim, remove spaces, upper-case.
    normalize: function(gstin) {
        return (gstin === null || gstin === undefined) ? '' : String(gstin).replace(/\s+/g, '').toUpperCase();
    },

    // check length, pattern and allowed state code. Returns {valid, reason}. 
    validateFormat: function(gstin) {
        var g = this.normalize(gstin);
        if (!g)
            return {
                valid: false,
                reason: 'GSTIN is empty'
            };
        if (g.length !== 15)
            return {
                valid: false,
                reason: 'GSTIN must be 15 characters (found ' + g.length + ')'
            };
        var stateCode = g.substring(0, 2);
        if (!/^[0-9]{2}$/.test(stateCode) || !this.STATES[stateCode])
            return {
                valid: false,
                reason: 'Invalid state code ' + stateCode
            };
        if (!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(g.substring(2, 12)))
            return {
                valid: false,
                reason: 'Characters 3-12 must be a valid PAN (5 letters, 4 digits, 1 letter)'
            };
        if (!/^[1-9A-Z]$/.test(g.charAt(12)))
            return {
                valid: false,
                reason: 'Character 13 (entity code) must be 1-9 or A-Z'
            };
        if (g.charAt(13) !== 'Z')
            return {
                valid: false,
                reason: 'Character 14 must be Z'
            };
        if (!this.FORMAT.test(g))
            return {
                valid: false,
                reason: 'GSTIN format is invalid'
            };
        return {
            valid: true,
            reason: ''
        };
    },

    // check GSTIN mod-36 check digit. Returns {valid, reason, expected}.
    checkDigit: function(gstin) {
        var g = this.normalize(gstin);
        if (g.length !== 15)
            return {
                valid: false,
                reason: 'GSTIN must be 15 characters',
                expected: ''
            };
        var sum = 0;
        for (var i = 0; i < 14; i++) {
            var v = this.CHARS.indexOf(g.charAt(i));
            if (v < 0)
                return {
                    valid: false,
                    reason: 'Invalid character ' + g.charAt(i),
                    expected: ''
                };
            var p = v * ((i % 2 === 0) ? 1 : 2);
            sum += Math.floor(p / 36) + (p % 36);
        }
        var expected = this.CHARS.charAt((36 - (sum % 36)) % 36);
        if (g.charAt(14) !== expected)
            return {
                valid: false,
                reason: 'Check digit should be ' + expected,
                expected: expected
            };
        return {
            valid: true,
            reason: '',
            expected: expected
        };
    },

    // state code and name. Returns {code, name} (name empty if unknown).
    extractState: function(gstin) {
        var code = this.normalize(gstin).substring(0, 2);
        return {
            code: code,
            name: this.STATES[code] || ''
        };
    },

    // Convenience: everything in one call. 
    validate: function(gstin) {
        var g = this.normalize(gstin);
        var fmt = this.validateFormat(g);
        if (!fmt.valid)
            return {
                valid: false,
                reason: fmt.reason,
                gstin: g,
                stateCode: '',
                stateName: ''
            };
        var chk = this.checkDigit(g);
        if (!chk.valid)
            return {
                valid: false,
                reason: chk.reason,
                gstin: g,
                stateCode: '',
                stateName: ''
            };
        var st = this.extractState(g);
        return {
            valid: true,
            reason: '',
            gstin: g,
            stateCode: st.code,
            stateName: st.name
        };
    },


    // Normalize supplier names
    normalizeName: function(name) {
        if (name === null || name === undefined)
            return '';

        name = String(name).toLowerCase().trim();

        // Remove M/s prefix
        name = name.replace(/^m\s*\/\s*s\.?\s*/i, '');

        // Remove punctuation
        name = name.replace(/[^a-z0-9\s]/g, ' ');

        // Remove extra spaces
        name = name.replace(/\s+/g, ' ').trim();

        // Remove legal suffixes from the end
        var suffixes = [
            'pvt', 'private', 'ltd',
            'limited', 'llp', 'co', 'company'
        ];

        var words = name ? name.split(' ') : [];

        while (words.length > 0) {
            var last = words[words.length - 1];

            if (suffixes.indexOf(last) !== -1) {
                words.pop();
            } else {
                break;
            }
        }

        return words.join(' ').trim();
    },

    // Compare submitted name with legal and trade names
    compareNames: function(submittedName, legalName, tradeName) {
        var submitted = this.normalizeName(submittedName);
        var legal = this.normalizeName(legalName);
        var trade = this.normalizeName(tradeName);

        var threshold = parseFloat(
            gs.getProperty(
                'x_2078844_gstin_0.gstin.name.partial.threshold', '0.8'
            )
        );

        if (isNaN(threshold) || threshold < 0 || threshold > 1)
            threshold = 0.8;

        function compareTwoNames(name1, name2) {
            if (!name1 || !name2) {
                return {
                    result: 'Mismatch',
                    score: 0
                };
            }

            // Exact match
            if (name1 === name2) {
                return {
                    result: 'Match',
                    score: 1
                };
            }

            var words1 = name1.split(' ');
            var words2 = name2.split(' ');
            var common = 0;

            for (var i = 0; i < words1.length; i++) {
                if (words2.indexOf(words1[i]) !== -1)
                    common++;
            }

            // Calculate token overlap
            var score = common /
                Math.min(words1.length, words2.length);

            score = Math.round(score * 100) / 100;

            if (score >= threshold && common > 0) {
                return {
                    result: 'Partial',
                    score: score
                };
            }

            return {
                result: 'Mismatch',
                score: score
            };
        }

        var legalResult = compareTwoNames(submitted, legal);
        var tradeResult = compareTwoNames(submitted, trade);

        var best = legalResult;
        var matchedAgainst = 'legal';

        // Prefer Match, then Partial, then Mismatch
        var rank = {
            'Mismatch': 0,
            'Partial': 1,
            'Match': 2
        };

        if (
            rank[tradeResult.result] > rank[best.result] ||
            (
                rank[tradeResult.result] === rank[best.result] &&
                tradeResult.score > best.score
            )
        ) {
            best = tradeResult;
            matchedAgainst = 'trade';
        }

        return {
            match: best.result.toLowerCase(),
            result: best.result,
            score: best.score,
            matchedAgainst: matchedAgainst,
            legalResult: legalResult.result,
            legalScore: legalResult.score,
            tradeResult: tradeResult.result,
            tradeScore: tradeResult.score
        };
    },

    type: 'GSTINUtil'
};
